async function search(){const topic=$('topicInput').value.trim();if(!topic)return;$('searchBtn').textContent='Searching...';let live=[];try{const from=$('fromYear').value,to=$('toYear').value;const r=await fetch(`https://api.openalex.org/works?search=${encodeURIComponent(topic)}&filter=from_publication_date:${from}-01-01,to_publication_date:${to}-12-31&per-page=${count}&sort=relevance_score:desc`);const d=await r.json();live=(d.results||[]).filter(x=>x.title).map(x=>({title:x.title,year:x.publication_year,authors:(x.authorships||[]).slice(0,3).map(a=>a.author.display_name).join(' - '),venue:x.primary_location?.source?.display_name,url:x.primary_location?.landing_page_url||x.doi||x.open_access?.oa_url||`https://openalex.org/${x.id}`,abstract:x.abstract_inverted_index?Object.keys(x.abstract_inverted_index).sort((a,b)=>x.abstract_inverted_index[a][0]-x.abstract_inverted_index[b][0]).join(' '):'',tags:['OpenAlex',x.open_access?.is_oa?'Open access':'Research'],live:true}));}catch(e){}papers=live.length?live:fallback.slice(0,count);$('searchBtn').textContent='Search papers';render(papers);toast(live.length?`Found ${live.length} papers from OpenAlex`:'Showing curated results - live source unavailable')}
function escapeHtml(value){return String(value||'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function exportPdf(){const rows=papers.map((p,i)=>'<tr><td class="paper-number">'+(i+1)+'</td><td><strong>'+escapeHtml(p.title)+'</strong><br><a href="'+escapeHtml(p.url)+'" target="_blank" rel="noopener noreferrer">Open paper</a></td><td>'+escapeHtml(p.authors||'Authors not listed')+'</td><td>'+escapeHtml(summarize(p))+'</td></tr>').join('');const generatedDate=new Date().toLocaleDateString(undefined,{year:'numeric',month:'long',day:'numeric'});const win=window.open('','_blank');if(!win){toast('Please allow pop-ups to export the PDF');return}const printDoc='<!doctype html><html><head><meta charset="utf-8"><title>Papertrail - Paper brief</title><style>@page{size:A4;margin:16mm 20mm 16mm 16mm}*{box-sizing:border-box}html,body{margin:0;padding:0}body{font-family:Futura,"Century Gothic","Trebuchet MS",Arial,sans-serif;color:#24191d;padding:0 11mm 0 0;font-size:10.5pt;line-height:1.45}header{border-bottom:2px solid #6b1f2a;padding:0 0 12px;margin:0 0 16px}h1{font-family:Georgia,"Times New Roman",serif;font-size:24pt;line-height:1.08;margin:0 0 4px;color:#6b1f2a}h2{font-size:10pt;letter-spacing:2px;text-transform:uppercase;margin:0;color:#a8792d}p.meta{margin:7px 0 0;color:#6f625c;font-size:9.5pt}table{border-collapse:collapse;width:100%;table-layout:fixed;font-size:9pt}col.number{width:5%}col.title{width:33%}col.authors{width:22%}col.brief{width:40%}thead{display:table-header-group}tr{break-inside:avoid;page-break-inside:avoid}th,td{border:1px solid #d9cdbf;padding:8px 9px;vertical-align:top;text-align:left;overflow-wrap:anywhere;word-break:normal}th{background:#f0e3ce;color:#6b1f2a;font-size:8.5pt;letter-spacing:.4px}td{background:#fffdf8}td.paper-number{font-weight:700;color:#a8792d;text-align:center}td strong{font-family:Georgia,"Times New Roman",serif;font-size:10pt;line-height:1.25}a{color:#1d6670;text-decoration:underline;overflow-wrap:anywhere}.print-watermark{position:fixed;right:-1mm;top:50%;transform:translateY(-50%) rotate(180deg);writing-mode:vertical-rl;color:#6b1f2a;opacity:.42;font-size:8pt;letter-spacing:1.5px;white-space:nowrap}@media print{.print-watermark{display:block}a{color:#1d6670;text-decoration:underline}}@media screen{body{max-width:210mm;margin:18px auto;padding:18px 22mm 18px 18px;box-shadow:0 0 0 1px #eadfce;background:#fffdf8}.print-watermark{position:fixed}}</style></head><body><div class="print-watermark">Made by Ajay</div><header><h2>Papertrail</h2><h1>Paper Brief</h1><p class="meta">'+papers.length+' papers included · Generated '+generatedDate+' · Use your browser print dialog and choose "Save as PDF".</p></header><table><colgroup><col class="number"><col class="title"><col class="authors"><col class="brief"></colgroup><thead><tr><th>#</th><th>Paper title</th><th>Authors</th><th>Brief</th></tr></thead><tbody>'+rows+'</tbody></table><script>window.onload=function(){setTimeout(function(){window.print()},250)}<\/script></body></html>';win.document.open();win.document.write(printDoc);win.document.close();toast('Paper Brief opened - choose Save as PDF')} document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){const url=save.dataset.save;const paper=papers.find(p=>p.url===url)||fallback.find(p=>p.url===url);if(saved.includes(url)){savedItems=savedItems.filter(p=>p.url!==url);saved=saved.filter(x=>x!==url)}else if(paper){savedItems=[...savedItems.filter(p=>p.url!==url),paper];saved=[...saved,url]}persistProfileData();localStorage.setItem('papertrail-saved',JSON.stringify(saved));$('savedCount').textContent=saved.length;render();toast(saved.includes(url)?'Saved to your reading list':'Removed from saved')}});
$('searchBtn').onclick=search;$('exportPdf').onclick=exportPdf;$('increase').onclick=()=>{count=Math.min(50,count+1);$('countValue').textContent=count};$('decrease').onclick=()=>{count=Math.max(1,count-1);$('countValue').textContent=count};$('customBtn').onclick=()=>$('customFilters').classList.toggle('hidden');$('applyCustom').onclick=()=>{let k=$('keywordFilter').value.toLowerCase();papers=papers.filter(p=>!k||`${p.title} ${p.abstract}`.toLowerCase().includes(k));render(papers);toast('Custom filters applied')};$('sortSelect').onchange=e=>{papers.sort((a,b)=>e.target.value==='newest'?b.year-a.year:e.target.value==='citations'?b.year-a.year:0);render()};
document.querySelectorAll('.suggestion-chips button').forEach(b=>b.onclick=()=>{$('aiInput').value=b.dataset.prompt;sendAI()});function sendAI(){const q=$('aiInput').value.trim();if(!q)return;const thread=$('aiThread');thread.insertAdjacentHTML('beforeend',`<div class="user-message">${escapeHtml(q)}</div>`);const lower=q.toLowerCase();let answer=lower.includes('gap')?'Research gap and next steps: the set relies heavily on static FEA and optimization, while fewer studies connect material variation, vibration, impact, manufacturing tolerances, and full-flight testing. A strong next project would compare optimized geometries under identical payload and thrust conditions, report mesh convergence and sensitivity, then validate the best design experimentally. Track mass, stress, displacement, natural frequency, fatigue life, safety factor, and manufacturing repeatability.':lower.includes('practical')?'Practical reading guide: begin with topology optimization and 3D-printing papers to understand geometry and manufacturability. Then study the composite-wing work for simulation-to-experiment validation, followed by payload and ducted-drone papers for operational constraints. Compare material models, boundary conditions, load cases, mesh quality, safety factors, validation methods, cost, and build complexity.':lower.includes('method')||lower.includes('compare')?'Methods and evidence: the papers use topology or generative optimization to reduce mass, finite element analysis to estimate stress and displacement, composite or additive materials to improve strength-to-weight, and selected experiments to test whether simulations are realistic. The most important comparison is not only the reported result; it is the quality of the assumptions, mesh convergence, material data, boundary conditions, load cases, and experimental validation.':'Detailed synthesis: the collection points to a common design challenge—reduce drone mass without losing stiffness, strength, stability, or manufacturability. Optimization proposes efficient shapes, FEA tests structural response, and experiments determine whether the model survives real-world variation. The strongest papers should be judged by transparent assumptions, realistic loading, validated material properties, safety margins, and reproducible testing. Ask about methods, limitations, practical papers, comparisons, or a research gap for a deeper breakdown.';thread.insertAdjacentHTML('beforeend',`<div class="ai-message"><span class="mini-spark">AI</span><p>${answer}</p></div>`);$('aiInput').value='';thread.scrollTop=thread.scrollHeight} $('aiSend').onclick=sendAI;$('aiInput').addEventListener('keydown',e=>{if(e.key==='Enter')sendAI()});
document.querySelectorAll('.nav-item').forEach(n=>n.onclick=()=>{document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));n.classList.add('active');$('viewLabel').textContent=n.textContent.trim().replace(/\d+$/,'');if(n.dataset.view==='saved'){const set=savedItems;$('emptyState').classList.toggle('hidden',set.length>0);$('results').classList.toggle('hidden',!set.length);if(set.length)render(set)}else{$('emptyState').classList.add('hidden');$('results').classList.remove('hidden');render(papers)}});$('savedCount').textContent=saved.length;render();
$('profileBtn').onclick=openProfileModal;$('profileClose').onclick=closeProfileModal;$('profileSave').onclick=()=>{const selected=$('profileSelect').value;const typed=$('profileName').value.trim();if(selected){activeProfileId=selected;activeProfile=profiles.find(p=>p.id===selected)}else if(typed){const id=typed.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||`profile-${Date.now()}`;activeProfile={id,name:typed};profiles=[...profiles.filter(p=>p.id!==id),activeProfile];activeProfileId=id;localStorage.setItem(profileStoreKey,JSON.stringify(profiles))}else{toast('Enter a profile name or choose an existing profile');return}localStorage.setItem(activeProfileKey,activeProfileId);savedItems=loadProfileData();if(!savedItems.length&&profiles.length===1){const old=JSON.parse(localStorage.getItem('papertrail-saved')||'[]');savedItems=fallback.filter(p=>Array.isArray(old)&&old.includes(p.url));if(savedItems.length)persistProfileData()}saved=savedItems.map(p=>p.url);refreshProfileUi();$('savedCount').textContent=saved.length;$('emptyState').classList.add('hidden');$('results').classList.remove('hidden');render(papers);closeProfileModal();toast(`Switched to ${activeProfile.name}`)};refreshProfileUi();if(!activeProfile)openProfileModal();
refreshProfileUi=()=>{$('profileBtn').textContent=(activeProfile?.name||'Profile').slice(0,2).toUpperCase();$('profileTitle').textContent=activeProfile?`${activeProfile.name}'s profile`:'Create your profile';$('profileName').value=activeProfile?.name||'';$('profileSelect').innerHTML='<option value="">Create a new profile</option>'+profiles.map(p=>`<option value="${p.id}" ${p.id===activeProfileId?'selected':''}>${p.name}</option>`).join('');$('profileSave').textContent=activeProfile?'Save or switch':'Create profile'};
refreshProfileUi();$('profileSave').onclick=()=>{const selected=$('profileSelect').value;const typed=$('profileName').value.trim();if(selected&&selected===activeProfileId&&typed){activeProfile.name=typed;profiles=profiles.map(p=>p.id===activeProfileId?activeProfile:p)}else if(selected){activeProfileId=selected;activeProfile=profiles.find(p=>p.id===selected)}else if(typed){const id=typed.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||`profile-${Date.now()}`;activeProfile={id,name:typed};profiles=[...profiles,activeProfile];activeProfileId=id}else{return toast('Enter a profile name or choose an existing profile')}localStorage.setItem(profileStoreKey,JSON.stringify(profiles));localStorage.setItem(activeProfileKey,activeProfileId);savedItems=loadProfileData();saved=savedItems.map(p=>p.url);$('savedCount').textContent=saved.length;refreshProfileUi();closeProfileModal();render(papers);toast(`Profile updated: ${activeProfile.name}`)};


function profileHash(value){let h=2166136261;for(let i=0;i<value.length;i++)h=Math.imul(h^value.charCodeAt(i),16777619);return (h>>>0).toString(16)}
profiles=profiles.map(p=>({...p,passwordHash:p.passwordHash||''}));
refreshProfileUi=()=>{$('profileBtn').textContent=(activeProfile?.name||'Profile').slice(0,2).toUpperCase();$('profileTitle').textContent=activeProfile?(activeProfile.name+"'s profile"):'Create your profile';$('profileName').value=activeProfile?.name||'';$('profilePassword').value='';$('profileSelect').innerHTML='<option value="">Create a new profile</option>'+profiles.map(p=>'<option value="'+p.id+'" '+(p.id===activeProfileId?'selected':'')+'>'+p.name+'</option>').join('');$('profileSave').textContent=activeProfile?'Save or switch':'Create profile'};
refreshProfileUi();$('profileSave').onclick=()=>{const selected=$('profileSelect').value,name=$('profileName').value.trim(),password=$('profilePassword').value;if(password.length<4)return toast('Password must be at least 4 characters');if(selected&&selected===activeProfileId){activeProfile.name=name||activeProfile.name;activeProfile.passwordHash=profileHash(password);profiles=profiles.map(p=>p.id===activeProfileId?activeProfile:p)}else if(selected){const target=profiles.find(p=>p.id===selected);if(!target||target.passwordHash!==profileHash(password))return toast('Incorrect profile password');activeProfileId=selected;activeProfile=target}else if(name){const id=name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||('profile-'+Date.now());activeProfile={id,name,passwordHash:profileHash(password)};profiles=[...profiles,activeProfile];activeProfileId=id}else{return toast('Enter a profile name or choose an existing profile')}localStorage.setItem(profileStoreKey,JSON.stringify(profiles));localStorage.setItem(activeProfileKey,activeProfileId);savedItems=loadProfileData();saved=savedItems.map(p=>p.url);$('savedCount').textContent=saved.length;refreshProfileUi();closeProfileModal();render(papers);toast('Profile updated: '+activeProfile.name)};

$('profileDelete').onclick=()=>{const id=$('profileSelect').value||activeProfileId;const target=profiles.find(p=>p.id===id);const password=$('profilePassword').value;if(!target)return toast('No profile selected');if(target.passwordHash&&target.passwordHash!==profileHash(password))return toast('Incorrect profile password');if(!window.confirm('Delete '+target.name+' and all its saved papers?'))return;profiles=profiles.filter(p=>p.id!==id);localStorage.removeItem('papertrail-data-'+id);if(id===activeProfileId){activeProfile=profiles[0]||null;activeProfileId=activeProfile?.id||'';savedItems=loadProfileData();saved=savedItems.map(p=>p.url);localStorage.setItem(activeProfileKey,activeProfileId)}localStorage.setItem(profileStoreKey,JSON.stringify(profiles));refreshProfileUi();$('savedCount').textContent=saved.length;closeProfileModal();render(papers);toast('Profile deleted')};

