/* v7.0 pagination: show 25 papers per page and keep the full result set available */
if(!window.__papertrailPagination){window.__papertrailPagination=true;var ptPageSize=25,ptPage=1,ptPageItems=[];var ptRenderBeforePagination=render;function ptRenderPage(){var total=Math.max(1,Math.ceil(ptPageItems.length/ptPageSize));ptPage=Math.min(Math.max(1,ptPage),total);var start=(ptPage-1)*ptPageSize;ptRenderBeforePagination(ptPageItems.slice(start,start+ptPageSize));if(typeof pt7Decorate==='function')pt7Decorate(ptPageItems.slice(start,start+ptPageSize));var box=$('pagination');if(box){box.classList.toggle('hidden',total<=1);$('pageTotal').textContent=total;$('pageNumber').value=ptPage;$('pagePrev').disabled=ptPage<=1;$('pageNext').disabled=ptPage>=total;$('pageSummary').textContent=ptPageItems.length?'Showing '+(start+1)+'–'+Math.min(start+ptPageSize,ptPageItems.length)+' of '+ptPageItems.length:''}}render=function(list=papers){ptPageItems=Array.isArray(list)?list:[];ptPage=1;ptRenderPage()};$('pagePrev').onclick=function(){ptPage--;ptRenderPage()};$('pageNext').onclick=function(){ptPage++;ptRenderPage()};$('pageNumber').onchange=function(){ptPage=Number(this.value)||1;ptRenderPage()};$('pageNumber').onkeydown=function(e){if(e.key==='Enter'){ptPage=Number(this.value)||1;ptRenderPage()}};render(papers)}

/* v7.1 Piku pet behavior: touch, scroll, repeated-click, and idle reactions */
if(!window.__pikuPetBehavior){window.__pikuPetBehavior=true;var pikuClicks=0,pikuClickTimer=null,pikuIdleTimer=null;function pikuSay(message,face){if(typeof petReact==='function')petReact(message);if(petCompanion){petCompanion.classList.remove('pet-happy','pet-tickled','pet-annoyed','pet-sleepy');if(face)petCompanion.classList.add('pet-'+face)}}function pikuResetFace(){if(petCompanion)petCompanion.classList.remove('pet-happy','pet-tickled','pet-annoyed','pet-sleepy')}function pikuIdle(){clearTimeout(pikuIdleTimer);pikuIdleTimer=setTimeout(function(){pikuSay('Piku is watching the research trail… give me a gentle tap if you need me.','sleepy')},18000)}if(petDog){petDog.addEventListener('click',function(){if(petCompanion.dataset.dragged==='true'){petCompanion.dataset.dragged='false';return}pikuClicks++;clearTimeout(pikuClickTimer);if(pikuClicks>=5){pikuSay('Arre, researcher! Five clicks? I am a pet, not a search button.','annoyed');pikuClicks=0}else if(pikuClicks>=3){pikuSay('Hehe! That tickles. One more and I may hide the papers.','tickled')}else{pikuSay('Good tap! Piku is ready to help you find a clever paper.','happy')}pikuClickTimer=setTimeout(function(){pikuClicks=0;pikuIdle()},900);pikuIdle()});petDog.addEventListener('dblclick',function(){pikuSay('Double tap accepted. Piku approves this level of curiosity.','happy')});petDog.addEventListener('contextmenu',function(e){e.preventDefault();pikuSay('A gentle touch, please. I have delicate Shih Tzu dignity.','annoyed')});petDog.addEventListener('pointerenter',function(){pikuSay('I see you hovering. Need help with the research?','happy');pikuIdle()});petDog.addEventListener('wheel',function(e){if(Math.abs(e.deltaY)>2){pikuSay('That tickles! Scrolling over my fur is very suspicious behaviour.','tickled');pikuIdle()}})}pikuIdle()}

/* v7.1 search-aware Piku animation */
if(!window.__pikuSearchBehavior){window.__pikuSearchBehavior=true;function pikuThinkStart(){if(!petCompanion)return;petCompanion.classList.remove('pet-happy','pet-tickled','pet-annoyed','pet-sleepy');petCompanion.classList.add('pet-thinking');pikuSay('Piku is climbing the mountain of research to find the clearest answer…','thinking')}function pikuThinkEnd(){if(!petCompanion)return;petCompanion.classList.remove('pet-thinking');pikuSay('Summit reached! Your research trail is ready.','happy')}if($('searchBtn'))$('searchBtn').addEventListener('click',function(){pikuThinkStart();setTimeout(pikuThinkEnd,1800)});if($('topicInput'))$('topicInput').addEventListener('keydown',function(e){if(e.key==='Enter'){pikuThinkStart();setTimeout(pikuThinkEnd,1800)}})}

/* v7.1 friendlier, funnier contextual roasts */
if(!window.__pikuRoastPack){window.__pikuRoastPack=true;var pikuRoasts={save:['Saved! Your reading list is growing faster than your excuses to read it.','Another paper adopted. Please give it a loving home in a folder.'],search:['I found the trail. Try not to wander into a 47-tab literature review.','Research mountain ahead! Pack curiosity, snacks, and a citation manager.','Searching now — because apparently one paper was not enough homework.'],empty:['A blank search? Even Piku cannot fetch a thesis from vibes alone.','Give me a topic, yaar. My tiny paws cannot type your thoughts.']};function pikuRoast(kind){var a=pikuRoasts[kind]||pikuRoasts.search;pikuSay(a[Math.floor(Math.random()*a.length)],kind==='save'?'happy':'thinking')}document.addEventListener('click',function(e){if(e.target.closest?.('[data-save]'))setTimeout(function(){pikuRoast('save')},120);if(e.target.closest?.('#searchBtn')){if(!$('topicInput').value.trim())pikuRoast('empty');else pikuRoast('search')}})}
